import{_ as r,o as a,c as n,ah as t}from"./chunks/framework.Bja9t6Wf.js";const o=JSON.parse('{"title":"Recherche: Die Inseraten-Affäre (Gekaufte Meinung)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/inseraten-affaere.md","filePath":"recherche/inseraten-affaere.md"}'),i={name:"recherche/inseraten-affaere.md"};function s(h,e,c,l,f,u){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="recherche-die-inseraten-affare-gekaufte-meinung" tabindex="-1">Recherche: Die Inseraten-Affäre (Gekaufte Meinung) <a class="header-anchor" href="#recherche-die-inseraten-affare-gekaufte-meinung" aria-label="Permalink to &quot;Recherche: Die Inseraten-Affäre (Gekaufte Meinung)&quot;">​</a></h1><p>In unserer Mockumentary untersuchen wir, wie man sich die Gunst der Presse nicht nur verdient, sondern schlichtweg kauft. Die Inseraten-Affäre der Ära Kurz ist hierfür das Lehrstück des 21. Jahrhunderts.</p><h2 id="das-prinzip" tabindex="-1">Das Prinzip <a class="header-anchor" href="#das-prinzip" aria-label="Permalink to &quot;Das Prinzip&quot;">​</a></h2><p>Steuergelder aus dem Finanzministerium wurden (mutmaßlich) für geschönte Umfragen in Boulevardzeitungen verwendet. Das Ziel: Ein künstliches Bild von Erfolg zu schaffen, das dann zum echten Erfolg führt.</p><h2 id="horten-parallele" tabindex="-1">Horten-Parallele <a class="header-anchor" href="#horten-parallele" aria-label="Permalink to &quot;Horten-Parallele&quot;">​</a></h2><p>Helmut Horten wusste schon früh: Wer die Schaufenster kontrolliert, kontrolliert die Begehrlichkeiten. In der Inseraten-Affäre wurden die Zeitungen zu den Schaufenstern der Macht.</p><hr><p><em>Wissenschaftlicher Fokus: Die Instrumentalisierung des Boulevards als politisches Werkzeug.</em></p>',8)])])}const p=r(i,[["render",s]]);export{o as __pageData,p as default};
